<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Controller;
use App\Core\HttpError;
final class FileController extends Controller {
 private function path(string $name):string{if(!preg_match('/^[a-f0-9]{64}$/D',$name))throw new HttpError(404,'Fayl topilmadi.');return dirname(__DIR__,2).'/storage/uploads/'.$name;}
 public function index():void{$u=$this->auth();$q=mb_substr(trim(is_string($_GET['q']??null)?$_GET['q']:''),0,120);$sql='SELECT a.*,l.title FROM attachments a JOIN listings l ON l.id=a.listing_id WHERE (a.original_name LIKE ? OR a.description LIKE ?)';$p=['%'.$q.'%','%'.$q.'%'];if($u['role']==='user'){$sql.=' AND l.user_id=?';$p[]=$u['id'];}$sql.=' ORDER BY a.id DESC';$this->view('files',['title'=>'Himoyalangan fayllar','items'=>$this->store->run($sql,$p)->fetchAll()]);}
 public function upload():void{$this->post();$u=$this->auth();$id=$this->id('listing_id',true);$this->listingAccess($id,true);$description=$this->text('description',2,500);$replace=empty($_POST['replace_id'])?null:$this->id('replace_id',true);$f=$_FILES['file']??null;if(!$f||is_array($f['name'])||$f['error']!==UPLOAD_ERR_OK)throw new HttpError(422,'Fayl yuklanmadi yoki hajmi server limitidan oshgan.');$extension=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['jpg'=>['image/jpeg',2],'jpeg'=>['image/jpeg',2],'png'=>['image/png',2],'webp'=>['image/webp',2],'pdf'=>['application/pdf',5],'mp4'=>['video/mp4',20]];if(!isset($allowed[$extension])||$allowed[$extension][0]!==$mime)throw new HttpError(422,'Kengaytma va MIME turi mos emas. Faqat JPG, PNG, WebP, PDF, MP4.');$size=filesize($f['tmp_name']);if(!$size||$size>$allowed[$extension][1]*1024*1024)throw new HttpError(422,'Fayl hajmi ruxsat etilgan limitdan oshgan.');if(str_starts_with($mime,'image/')&&!@getimagesize($f['tmp_name']))throw new HttpError(422,'Rasm buzilgan.');$name=bin2hex(random_bytes(32));$path=$this->path($name);if(!move_uploaded_file($f['tmp_name'],$path))throw new HttpError(500,'Faylni saqlab bo‘lmadi.');$old=null;$this->store->db->beginTransaction();try{$l=$this->store->run('SELECT * FROM listings WHERE id=? FOR UPDATE',[$id])->fetch();if(!$l||($u['role']!=='admin'&&(int)$l['user_id']!==(int)$u['id']))throw new HttpError(403,'Egalik huquqi yo‘q.');if($replace){$old=$this->store->run('SELECT * FROM attachments WHERE id=? FOR UPDATE',[$replace])->fetch();if(!$old||(int)$old['listing_id']!==$id)throw new HttpError(403,'Almashtiriladigan fayl shu e’longa tegishli emas.');$this->store->run('UPDATE attachments SET original_name=?,stored_name=?,mime=?,size=?,description=?,user_id=? WHERE id=?',[mb_substr(basename($f['name']),0,200),$name,$mime,$size,$description,$u['id'],$replace]);}else{$this->store->run('INSERT INTO attachments(listing_id,user_id,original_name,stored_name,mime,size,description) VALUES(?,?,?,?,?,?,?)',[$id,$u['id'],mb_substr(basename($f['name']),0,200),$name,$mime,$size,$description]);}$this->store->db->commit();}catch(\Throwable $e){$this->store->db->rollBack();@unlink($path);throw $e;}if($old&&is_file($this->path($old['stored_name']))&&!@unlink($this->path($old['stored_name'])))error_log('Old attachment cleanup required');flash($replace?'Fayl almashtirildi.':'Fayl biriktirildi.');redirect('listing',['id'=>$id]);}
 public function delete():void{$this->post();$u=$this->auth();$id=$this->id('id',true);if(($_POST['confirm']??'')!=='yes')throw new HttpError(422,'Fayl o‘chirishni tasdiqlang.');$a=$this->store->find('attachments',$id);if(!$a)throw new HttpError(404,'Fayl topilmadi.');$this->listingAccess((int)$a['listing_id'],true);$path=$this->path($a['stored_name']);$trash=$path.'.trash-'.bin2hex(random_bytes(4));$moved=false;$this->store->db->beginTransaction();try{$locked=$this->store->run('SELECT * FROM attachments WHERE id=? FOR UPDATE',[$id])->fetch();if(!$locked||$locked['stored_name']!==$a['stored_name'])throw new HttpError(409,'Fayl o‘zgargan; sahifani yangilang.');if(is_file($path)){if(!rename($path,$trash))throw new HttpError(500,'Faylni olib tashlab bo‘lmadi.');$moved=true;}$this->store->run('DELETE FROM attachments WHERE id=?',[$id]);$this->store->db->commit();}catch(\Throwable $e){$this->store->db->rollBack();if($moved)rename($trash,$path);throw $e;}if($moved&&!@unlink($trash))error_log('Attachment trash cleanup required');flash('Fayl o‘chirildi.');redirect('listing',['id'=>$a['listing_id']]);}
 public function download():void{$u=$this->auth();$a=$this->store->find('attachments',$this->id());if(!$a)throw new HttpError(404,'Fayl topilmadi.');$this->store->privateListing((int)$a['listing_id'],$u);$path=$this->path($a['stored_name']);if(!is_file($path))throw new HttpError(404,'Fayl diskda topilmadi.');header('Content-Type: '.$a['mime']);header('Content-Length: '.filesize($path));header("Content-Disposition: attachment; filename=\"download\"; filename*=UTF-8''".rawurlencode($a['original_name']));header('Cache-Control: private, no-store');readfile($path);}
}
